package com.example.gameworkbench.service;
import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import org.junit.jupiter.api.*; import org.mockito.ArgumentCaptor; import com.example.gameworkbench.entity.*; import com.example.gameworkbench.mapper.KnowledgeChunkMapper;
class KnowledgeIndexingServiceTest { KnowledgeChunkMapper mapper=mock(KnowledgeChunkMapper.class); InMemoryVectorStore store=new InMemoryVectorStore(); KnowledgeIndexingService service=new KnowledgeIndexingService(new KnowledgeChunker(),new FakeEmbeddingProvider(),store,mapper); KnowledgeDocument doc(){KnowledgeDocument d=new KnowledgeDocument();d.setId(1L);d.setProjectId(2L);d.setDocumentUuid("doc");d.setVersion(1);d.setDeleted(0);return d;} @Test void indexesWithIsolatedMetadataAndIsIdempotent(){when(mapper.selectCount(any())).thenReturn(0L); service.index(doc(),"hello"); ArgumentCaptor<KnowledgeChunk> c=ArgumentCaptor.forClass(KnowledgeChunk.class);verify(mapper).insert(c.capture()); assertThat(store.metadata(c.getValue().getVectorRef())).containsEntry("projectId","2").containsEntry("documentUuid","doc").containsEntry("status","ACTIVE"); when(mapper.selectCount(any())).thenReturn(1L);service.index(doc(),"hello");verify(mapper,times(1)).insert(any(KnowledgeChunk.class));} @Test void doesNotIndexDeletedDocument(){KnowledgeDocument d=doc();d.setDeleted(1);service.index(d,"hello");verifyNoInteractions(mapper);} }
